/**
 * **생성 파일이다. 직접 고치지 않는다** — `npm run import:circuits`가 통째로 덮어쓴다.
 *
 * 출처: bacinger/f1-circuits (MIT) — 원 데이터는 OpenStreetMap 기여자 (ODbL 1.0).
 * 좌표는 등거리 원통도법으로 편 뒤 균일 배율로 줄인 것이라 **모양이 실제 그대로**다.
 * 가로세로를 따로 늘리면 코스가 실제와 다른 모양이 된다 — 그러면 실제 트랙을
 * 쓰는 의미가 없다.
 *
 * 비어 있으면 화면은 예전처럼 지어낸 코스로 돈다 (`pickCircuit` 참조).
 */
export interface CircuitData {
  /** 출처 데이터의 id. 어디서 왔는지 추적용 */
  id: string;
  name: string;
  location: string;
  /** 실제 코스 길이 (m). 화면에는 안 쓴다 — 출처 대조용이다. */
  lengthM: number;
  /** 좌표계 가로 비율. 코스 bbox에서 나온 값이다. */
  aspect: number;
  /** 가장 긴 직선의 한가운데. 피트는 실제로도 거기 있다. */
  pitEntry: number;
  pitExit: number;
  /** (0..1000×aspect) × (0..1000) 좌표. 호 길이 등간격, 시계 방향, 정수. */
  points: [number, number][];
}

